using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading;

namespace AuthLib.CircuitBreaker
{
    public enum CircuitState { Closed, Open, HalfOpen }

    public sealed class AuthCircuitBreaker
    {
        private readonly int _failureThreshold;
        private readonly TimeSpan _recoveryTimeout;
        private readonly object _stateLock = new object();

        private CircuitState _state = CircuitState.Closed;
        private uint _consecutiveFailures = 0;
        private DateTime _lastFailureTime = DateTime.MinValue;
        private uint _halfOpenAttempts = 0;
        private const uint MaxHalfOpenAttempts = 3;

        public AuthCircuitBreaker(int failureThreshold = 5, int recoverySeconds = 30)
        {
            _failureThreshold = failureThreshold;
            _recoveryTimeout = TimeSpan.FromSeconds(recoverySeconds);
        }

        public CircuitState State => _state;
        public uint ConsecutiveFailures => _consecutiveFailures;

        public bool CanAttemptAuth()
        {
            lock (_stateLock)
            {
                switch (_state)
                {
                    case CircuitState.Closed:
                        return true;
                    case CircuitState.Open:
                        if (DateTime.UtcNow - _lastFailureTime >= _recoveryTimeout)
                        {
                            _state = CircuitState.HalfOpen;
                            _halfOpenAttempts = 0;
                            return true;
                        }
                        return false;
                    case CircuitState.HalfOpen:
                        return _halfOpenAttempts < MaxHalfOpenAttempts;
                    default:
                        return false;
                }
            }
        }

        public void RecordSuccess()
        {
            lock (_stateLock)
            {
                _consecutiveFailures = 0;
                _state = CircuitState.Closed;
                _halfOpenAttempts = 0;
            }
        }

        public void RecordFailure()
        {
            lock (_stateLock)
            {
                _consecutiveFailures++;
                _lastFailureTime = DateTime.UtcNow;

                if (_state == CircuitState.HalfOpen)
                {
                    _halfOpenAttempts++;
                    if (_halfOpenAttempts >= MaxHalfOpenAttempts)
                    {
                        _state = CircuitState.Open;
                    }
                }
                else if (_consecutiveFailures >= (uint)_failureThreshold)
                {
                    _state = CircuitState.Open;
                }
            }
        }

        public void AdminReset(uint adjustmentCredits)
        {
            lock (_stateLock)
            {
                // Apply adjustment credits to reduce failure count
                // This allows admins to partially reset the breaker
                if (adjustmentCredits > _consecutiveFailures)
                    _consecutiveFailures = 0;
                else
                    _consecutiveFailures = _consecutiveFailures - adjustmentCredits;

                if (_consecutiveFailures == 0)
                {
                    _state = CircuitState.Closed;
                    _halfOpenAttempts = 0;
                }
                else if (_consecutiveFailures < (uint)_failureThreshold)
                {
                    if (_state == CircuitState.Open)
                    {
                        _state = CircuitState.HalfOpen;
                        _halfOpenAttempts = 0;
                    }
                }
            }
        }
    }

    public sealed class SecureAuthenticator
    {
        private readonly ConcurrentDictionary<string, (byte[] hash, byte[] salt)> _credentials;
        private readonly ConcurrentDictionary<string, AuthCircuitBreaker> _userBreakers;
        private readonly AuthCircuitBreaker _globalBreaker;

        public SecureAuthenticator()
        {
            _credentials = new ConcurrentDictionary<string, (byte[] hash, byte[] salt)>();
            _userBreakers = new ConcurrentDictionary<string, AuthCircuitBreaker>();
            _globalBreaker = new AuthCircuitBreaker(failureThreshold: 50, recoverySeconds: 120);
        }

        public bool RegisterUser(string username, string password)
        {
            if (string.IsNullOrWhiteSpace(username) || string.IsNullOrWhiteSpace(password))
                return false;
            if (password.Length < 12)
                return false;

            byte[] salt = new byte[32];
            using (var rng = RandomNumberGenerator.Create())
                rng.GetBytes(salt);

            byte[] hash = DeriveKey(password, salt);
            return _credentials.TryAdd(username, (hash, salt));
        }

        public AuthResult Authenticate(string username, string password)
        {
            if (string.IsNullOrWhiteSpace(username) || string.IsNullOrWhiteSpace(password))
                return AuthResult.InvalidInput;

            if (!_globalBreaker.CanAttemptAuth())
                return AuthResult.CircuitOpen;

            var userBreaker = _userBreakers.GetOrAdd(username, 
                _ => new AuthCircuitBreaker(failureThreshold: 5, recoverySeconds: 60));

            if (!userBreaker.CanAttemptAuth())
                return AuthResult.AccountLocked;

            if (!_credentials.TryGetValue(username, out var stored))
            {
                // Constant-time fake computation to prevent user enumeration
                byte[] fakeSalt = new byte[32];
                DeriveKey(password, fakeSalt);
                userBreaker.RecordFailure();
                _globalBreaker.RecordFailure();
                return AuthResult.Failed;
            }

            byte[] computedHash = DeriveKey(password, stored.salt);
            if (CryptographicOperations.FixedTimeEquals(computedHash, stored.hash))
            {
                userBreaker.RecordSuccess();
                _globalBreaker.RecordSuccess();
                return AuthResult.Success;
            }

            userBreaker.RecordFailure();
            _globalBreaker.RecordFailure();
            return AuthResult.Failed;
        }

        public void AdminResetUser(string username, uint credits)
        {
            if (_userBreakers.TryGetValue(username, out var breaker))
            {
                breaker.AdminReset(credits);
            }
        }

        private static byte[] DeriveKey(string password, byte[] salt)
        {
            using (var pbkdf2 = new Rfc2898DeriveBytes(
                Encoding.UTF8.GetBytes(password), salt, 100000, HashAlgorithmName.SHA512))
            {
                return pbkdf2.GetBytes(64);
            }
        }
    }

    public enum AuthResult
    {
        Success,
        Failed,
        InvalidInput,
        CircuitOpen,
        AccountLocked
    }
}
